#include <nRF24L01.h>
#include <RF24.h>

struct Packet {
  int8_t pitch;
  int8_t roll;
};

Packet data;
RF24 radio(7, 8);

void loop() {
  // Read complementary filtered pitch and roll
  data.pitch = constrain(map(filteredPitch, -45, 45, -100, 100), -100, 100);
  data.roll  = constrain(map(filteredRoll,  -45, 45, -100, 100), -100, 100);

  radio.write(&data, sizeof(Packet));
  delay(20); // 50 Hz control loop
}
